<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';require_once __DIR__.'/includes/csrf.php';
$u=require_login();$id=(int)($_GET['id']??$_POST['id']??0);$pdo=db();
$s=$pdo->prepare('SELECT * FROM listings WHERE id=? AND user_id=? LIMIT 1');$s->execute([$id,$u['id']]);$l=$s->fetch();if(!$l){http_response_code(403);exit('Listing not available.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');$category=strtolower(trim($_POST['category']??''));$brand=trim($_POST['brand']??'');$condition=$_POST['condition']??'';$price=(float)($_POST['price']??0);$location=trim($_POST['location']??'');$lat=$_POST['latitude']!==''?$_POST['latitude']:null;$lng=$_POST['longitude']!==''?$_POST['longitude']:null;if(strlen($title)<3||strlen($description)<10||$category===''||$price<=0||!in_array($condition,['new','excellent','good','fair','poor'],true)){flash('error','Complete all required fields.');redirect('/edit-listing.php?id='.$id);} $q=$pdo->prepare("UPDATE listings SET title=?,description=?,category=?,brand=?,item_condition=?,price=?,location=?,latitude=?,longitude=?,status='pending',fraud_checked=0,updated_at=NOW() WHERE id=? AND user_id=?");$q->execute([$title,$description,$category,$brand,$condition,$price,$location,$lat,$lng,$id,$u['id']]);$result=run_fraud_analysis($id);flash($result?'success':'error',$result?'Listing updated and re-analyzed.':'Listing updated; fraud analysis temporarily unavailable.');redirect('/listing.php?id='.$id);}
$pageTitle='Edit Listing';include __DIR__.'/includes/header.php';?><form class="form-card" method="post"><h1>Edit listing</h1><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><div class="field full"><label>Title</label><input name="title" value="<?=e($l['title'])?>" required></div><div class="field full"><label>Description</label><textarea name="description" required><?=e($l['description'])?></textarea></div><div class="field"><label>Category</label><input name="category" value="<?=e($l['category'])?>" required></div><div class="field"><label>Brand</label><input name="brand" value="<?=e($l['brand'])?>"></div><div class="field"><label>Condition</label><select name="condition"><?php foreach(['new','excellent','good','fair','poor'] as $v):?><option <?=$l['item_condition']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="field"><label>Price</label><input type="number" name="price" value="<?=e((string)$l['price'])?>" min="1" required></div><div class="field full"><label>Location</label><input name="location" value="<?=e($l['location'])?>" required></div><div class="field"><label>Latitude</label><input name="latitude" value="<?=e((string)$l['latitude'])?>"></div><div class="field"><label>Longitude</label><input name="longitude" value="<?=e((string)$l['longitude'])?>"></div></div><div class="actions"><button type="button" class="btn btn-light" data-use-location>Use my location</button><button class="btn">Save & Re-analyze</button></div></form><?php include __DIR__.'/includes/footer.php';?>